<?php
declare(strict_types=1);
require __DIR__.'/../public/curator_helpers.php';
$dsn=getenv('LIBRARY3_SCHEMA_TEST_DSN');if(!$dsn)throw new RuntimeException('Disposable DSN required.');$db=new PDO($dsn,getenv('LIBRARY3_SCHEMA_TEST_USER')?:'root',getenv('LIBRARY3_SCHEMA_TEST_PASSWORD')?:'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);
if(!preg_match('/^library3_schema_test[a-zA-Z0-9_]*$/D',(string)$db->query('SELECT DATABASE()')->fetchColumn()))throw new RuntimeException('Refusing non-test database.');
$schema=preg_replace('~/\*(?![!])[^*]*\*+(?:[^/*][^*]*\*+)*/~s','',file_get_contents(__DIR__.'/../00-basedata/sql/schema.sql'));$db->exec(preg_replace('/^\s*;\s*$/m','',$schema));$checks=0;
function ccheck(bool $ok,string $why):void{global $checks;$checks++;if(!$ok)throw new RuntimeException($why);}
function cpayload(PDO $db,array $ids,array $changes=[]):array{$s=$db->query('SELECT book_id id,title,series,record_status FROM Books WHERE book_id IN ('.implode(',',array_map('intval',$ids)).') ORDER BY book_id');$rows=curator_annotate($db,$s->fetchAll(PDO::FETCH_ASSOC),'Pelham');return $changes+['ids'=>$ids,'versions'=>array_column($rows,'curator_version','id'),'replace_author'=>true,'source_author_id'=>1,'new_author_name'=>'P G Wodehouse','search'=>'Pelham','set_series'=>false,'series'=>''];}
function clinks(PDO $db,int $id):array{return $db->query('SELECT author_id,author_ord,author_alias FROM Books_Authors WHERE book_id='.$id.' ORDER BY author_ord,author_id')->fetchAll(PDO::FETCH_ASSOC);}
$actor=['uid'=>1,'username'=>'TEST admin'];
$db->exec("INSERT INTO Users(user_id,username,password_hash,role) VALUES(1,'TEST admin','TEST hash','admin')");
$db->exec("INSERT INTO Authors(author_id,name,first_name,last_name,sort_name,is_hungarian) VALUES(1,'Pelham Grenville Wodehouse','Pelham Grenville','Wodehouse','Wodehouse, Pelham Grenville',0),(2,'P G Wodehouse','P G','Wodehouse','Wodehouse, P G',0),(3,'TEST Coauthor','TEST','Coauthor','Coauthor, TEST',0)");
for($i=1;$i<=7;$i++){$db->prepare('INSERT INTO Books(book_id,title,series,notes,record_status) VALUES(?,?,?,?,?)')->execute([$i,'TEST '.($i===6?'Pelham title':'book '.$i),'Old series','Keep notes',$i===5?'deleted':'active']);$db->prepare('INSERT INTO BookCopies(copy_id,book_id,format,record_status) VALUES(?,?,?,?)')->execute([$i,$i,$i===2?'epub':'print',$i===5?'deleted':'active']);}
$db->exec("INSERT INTO Books_Authors(book_id,author_id,author_ord,author_alias) VALUES(1,1,0,NULL),(1,3,1,'Keep alias'),(2,1,0,NULL),(3,1,1,NULL),(3,2,0,NULL),(4,1,0,NULL),(5,1,0,NULL),(6,3,0,NULL),(7,1,0,'Old alias'),(7,2,1,'Other alias')");
$authors=$db->query('SELECT * FROM Authors ORDER BY author_id')->fetchAll(PDO::FETCH_ASSOC);$copy_before=$db->query('SELECT * FROM BookCopies ORDER BY copy_id')->fetchAll(PDO::FETCH_ASSOC);
$r=curator_apply($db,cpayload($db,[1,2,3],['set_series'=>true,'series'=>'New series']),$actor);
ccheck($r['changed_books']===3&&$r['author_changes']===3&&$r['series_changes']===3,'Combined batch counts differ.');
ccheck(array_map('intval',array_column(clinks($db,1),'author_id'))===[2,3],'Coauthor lost or order changed.');ccheck(clinks($db,1)[1]['author_alias']==='Keep alias','Coauthor alias changed.');ccheck(count(clinks($db,3))===1,'Duplicate target link not merged.');ccheck((int)clinks($db,4)[0]['author_id']===1,'Unselected book changed.');ccheck($db->query('SELECT * FROM Authors ORDER BY author_id')->fetchAll(PDO::FETCH_ASSOC)===$authors,'Shared author metadata globally mutated.');ccheck($db->query('SELECT * FROM BookCopies ORDER BY copy_id')->fetchAll(PDO::FETCH_ASSOC)===$copy_before,'Copies changed.');ccheck((int)$db->query("SELECT COUNT(*) FROM AuthEvents WHERE event_type='catalog_curate'")->fetchColumn()===1,'Audit not committed.');
$stale=cpayload($db,[4]);$db->exec("UPDATE Books SET series='Concurrent edit' WHERE book_id=4");try{curator_apply($db,$stale,$actor);throw new LogicException('Stale batch accepted.');}catch(RuntimeException $e){ccheck($e->getCode()===409,'Wrong stale error.');}
$before=$db->query('SELECT * FROM Books_Authors ORDER BY book_id,author_id')->fetchAll(PDO::FETCH_ASSOC);$count=(int)$db->query('SELECT COUNT(*) FROM AuthEvents')->fetchColumn();
try{curator_apply($db,cpayload($db,[4,7],['set_series'=>true,'series'=>'Should roll back']),$actor);throw new LogicException('Alias conflict accepted.');}catch(InvalidArgumentException $e){ccheck(str_contains($e->getMessage(),'alias'),'Wrong alias conflict error.');}
ccheck($db->query('SELECT * FROM Books_Authors ORDER BY book_id,author_id')->fetchAll(PDO::FETCH_ASSOC)===$before,'Conflict partially changed links.');ccheck($db->query('SELECT series FROM Books WHERE book_id=4')->fetchColumn()==='Concurrent edit','Conflict changed series.');ccheck((int)$db->query('SELECT COUNT(*) FROM AuthEvents')->fetchColumn()===$count,'Failed batch logged success.');
try{curator_apply($db,cpayload($db,[5]),$actor);throw new LogicException('Archived book accepted.');}catch(RuntimeException $e){ccheck($e->getCode()===409,'Wrong archive rejection.');}
try{curator_apply($db,cpayload($db,[1],['source_author_id'=>3]),$actor);throw new LogicException('Unsearched coauthor accepted.');}catch(InvalidArgumentException $e){ccheck(str_contains($e->getMessage(),'keresés'),'Wrong source search rejection.');}
$r=curator_apply($db,cpayload($db,[4,6],['new_author_name'=>'TEST New Author','set_series'=>true,'series'=>'Mixed selection']),$actor);ccheck($r['author_changes']===1&&$r['series_changes']===2&&$r['author_not_present']===1,'Nonmatching author book was overwritten.');ccheck((int)clinks($db,6)[0]['author_id']===3,'Unrelated title match author changed.');ccheck((int)clinks($db,4)[0]['author_id']===($r['target_author']['id']),'New author not linked.');
$r=curator_apply($db,cpayload($db,[1],['replace_author'=>false,'set_series'=>true,'series'=>'']),$actor);ccheck($db->query('SELECT series FROM Books WHERE book_id=1')->fetchColumn()===null,'Explicit series clearing failed.');ccheck($db->query('SELECT series FROM Books WHERE book_id=2')->fetchColumn()==='New series','Series outside selection changed.');
$count=(int)$db->query('SELECT COUNT(*) FROM AuthEvents')->fetchColumn();$r=curator_apply($db,cpayload($db,[1],['replace_author'=>false,'set_series'=>true,'series'=>'']),$actor);ccheck($r['changed_books']===0&&(int)$db->query('SELECT COUNT(*) FROM AuthEvents')->fetchColumn()===$count,'No-op created changes/audit.');
$all=curator_annotate($db,$db->query('SELECT book_id id,title,series,record_status FROM Books ORDER BY book_id')->fetchAll(PDO::FETCH_ASSOC),'Wodehouse');ccheck(count($all)===7&&count($all[0]['curator_authors'])===2,'All-results metadata incomplete.');
ccheck(curator_author_matches('PELHAM',$authors[0]),'Case-insensitive source matching failed.');ccheck(curator_author_matches('Arviz',['name'=>'Árvíz']),'Accent-folded source matching failed.');
ccheck(curator_author_matches('Pelh_m%',['name'=>'Pelham Grenville Wodehouse']),'Search wildcard matching failed.');
$manifest=portable_manifest($db,[1,2,3,4,5,6,7]);ccheck(count($manifest['tables']['Books_Authors'])===9,'Portable author links changed unexpectedly.');ccheck($manifest['tables']['Books'][0]['series']===null,'Portable series changes omitted.');
echo json_encode(['ok'=>true,'checks'=>$checks,'features'=>['selected-only author links','coauthors/order/aliases','existing target reuse and duplicate merge','combined and series-only/clear','search-bound replacement','stale/archived rejection','atomic conflict rollback','new author and audit','portable metadata']],JSON_PRETTY_PRINT)."\n";
